function initSettingTab_configUI(tab_nav_container, tab_content_container) {
  const tab_nav = document.createElement("div");
  tab_nav_container.appendChild(tab_nav);
  tab_nav.classList.add("item");
  tab_nav.textContent = t2("Config");
  const tab_content = document.createElement("div");
  tab_content_container.appendChild(tab_content);
  tab_content.classList.add("item");
  tab_nav.setAttribute("index", "setting-ui");
  tab_content.setAttribute("index", "setting-ui");
  tab_nav.addEventListener("click", () => void init(tab_content));
  init(tab_content);
  function init(tab_content2) {
    tab_content2.innerHTML = "";
    const el_p = document.createElement("div");
    tab_content2.appendChild(el_p);
    el_p.textContent = t2("Config2");
    new SettingItem(tab_content2).setHeading(t2("Dict config"));
    new SettingItem(tab_content2).setName(t2("Dict path")).setDesc(t2("Dict path2")).addText(
      (text2) => text2.setValue(global_setting.config.dict_paths).onChange(async (value) => {
        global_setting.config.dict_paths = value;
        await global_setting.api.saveConfig();
      })
    );
    new SettingItem(tab_content2).setName(t2("Dict online source")).setDesc(t2("Dict online source2")).addDropdown((dropdown) => {
      dropdown.addOption("gitee", "Gitee");
      dropdown.addOption("github", "GitHub");
      dropdown.setValue(global_setting.config.dict_online_source);
      dropdown.onChange(async (value) => {
        global_setting.config.dict_online_source = value;
        await global_setting.api.saveConfig();
      });
    });
    new SettingItem(tab_content2).setHeading(t2("Dict index config"));
    new SettingItem(tab_content2).setName(t2("Pinyin index")).setDesc(t2("Pinyin index2")).addToggle(
      (toggle) => toggle.setValue(global_setting.config.pinyin_index).onChange(async (value) => {
        global_setting.config.pinyin_index = value;
        await global_setting.api.saveConfig();
      })
    );
    new SettingItem(tab_content2).setName(t2("Pinyin first index")).setDesc(t2("Pinyin first index2")).addToggle(
      (toggle) => toggle.setValue(global_setting.config.pinyin_first_index).onChange(async (value) => {
        global_setting.config.pinyin_first_index = value;
        await global_setting.api.saveConfig();
      })
    );
    new SettingItem(tab_content2).setName(t2("Index engine")).setDesc(t2("Index engine2")).addDropdown((dropdown) => {
      dropdown.addOption("reverse", "Reverse");
      dropdown.addOption("trie", "Trie");
      dropdown.setValue(global_setting.config.search_engine);
      dropdown.onChange(async (value) => {
        global_setting.config.search_engine = value;
        await global_setting.api.saveConfig();
      });
    });
    new SettingItem(tab_content2).setHeading(t2("Other config"));
    new SettingItem(tab_content2).setName(t2("Note path")).setDesc(t2("Note path2")).addText(
      (text2) => text2.setValue(global_setting.config.note_paths).onChange(async (value) => {
        global_setting.config.note_paths = value;
        await global_setting.api.saveConfig();
      })
    );
    new SettingItem(tab_content2).setName(t2("Debug mode")).setDesc(t2("Debug mode2")).addToggle(
      (toggle) => toggle.setValue(global_setting.isDebug).onChange(async (value) => {
        global_setting.isDebug = value;
        await global_setting.api.saveConfig();
      })
    );
    new SettingItem(tab_content2).setName(t2("Auto show toolbar on select")).setDesc(t2("Auto show toolbar on select2")).addToggle(
      (toggle) => toggle.setValue(global_setting.config.auto_show_toolbar_on_select).onChange(async (value) => {
        global_setting.config.auto_show_toolbar_on_select = value;
        await global_setting.api.saveConfig();
      })
    );
    new SettingItem(tab_content2).setName(t2("Server port")).setDesc(t2("Server port2")).addText(
      (text2) => text2.setType("number").setValue(String(global_setting.config.server_port)).onChange(async (value, el) => {
        const port = Number(value);
        if (Number.isNaN(port) || port <= 0 || port >= 65536) {
          el.value = String(global_setting.config.server_port);
          console.error("Invalid port number " + port + ", reset to", global_setting.config.server_port);
          global_setting.api.notify("Invalid port number: " + port);
          return;
        }
        global_setting.config.server_port = port;
        await global_setting.api.saveConfig();
      })
    );
    if (global_setting.platform === "app") {
      new SettingItem(tab_content2).setHeading(t2("App config"));
      new SettingItem(tab_content2).setName(t2("Send text method")).setDesc(t2("Send text method2")).addDropdown((dropdown) => {
        dropdown.addOption("clipboard", "Clipboard");
        dropdown.addOption("keyboard", "Keyboard");
        dropdown.addOption("auto", "Auto");
        dropdown.setValue(global_setting.config.send_text_method);
        dropdown.onChange(async (value) => {
          global_setting.config.send_text_method = value;
          await global_setting.api.saveConfig();
        });
      });
      new SettingItem(tab_content2).setName(t2("Is use ad shortcut")).setDesc(t2("Is use ad shortcut2")).addToggle(
        (toggle) => toggle.setValue(global_setting.config.app_ad_shortcut).onChange(async (value) => {
          global_setting.config.app_ad_shortcut = value;
          await global_setting.api.saveConfig();
        })
      );
    }
  }
}
