function json2table(container, data2, data_header) {
  container.innerHTML = "";
  container.dataset.viewmode = "table";
  const table = document.createElement("table");
  container.appendChild(table);
  table.classList.add("dataview-table");
  const table_thead = document.createElement("thead");
  table.appendChild(table_thead);
  const tr = document.createElement("tr");
  table_thead.appendChild(tr);
  for (const header_item of data_header) {
    const td = document.createElement("td");
    tr.appendChild(td);
    td.textContent = header_item.name;
  }
  const table_tbody = document.createElement("tbody");
  table.appendChild(table_tbody);
  data2.forEach((item) => {
    const tr2 = document.createElement("tr");
    table_tbody.appendChild(tr2);
    tr2.setAttribute("target-id", item.id);
    for (const header_item of data_header) {
      const td = document.createElement("td");
      tr2.appendChild(td);
      header_item.callback(td, item);
    }
  });
}
function json2card(container, data2, data_header) {
  container.innerHTML = "";
  container.dataset.viewmode = "card";
  const div = document.createElement("div");
  container.appendChild(div);
  div.classList.add("dataview-card");
  data2.forEach((item) => {
    const card = document.createElement("div");
    div.appendChild(card);
    card.classList.add("card");
    for (const header_item of data_header) {
      const card_item = document.createElement("div");
      card.appendChild(card_item);
      const card_item1 = document.createElement("span");
      card_item.appendChild(card_item1);
      card_item.innerText = header_item.name + ": ";
      const card_item2 = document.createElement("span");
      card_item.appendChild(card_item2);
      header_item.callback(card_item2, item);
    }
  });
}

